<script setup lang="ts">
import type { NuxtError } from '#app';

const props = defineProps<{ error: NuxtError }>();

const notFound = computed(() => props.error.statusCode === 404);
useSeoMeta({ title: notFound.value ? 'Pagina niet gevonden' : 'Er ging iets mis', robots: 'noindex' });
</script>

<template>
  <NuxtLayout>
    <section class="container-page py-24 text-center">
      <p class="label-mono text-sherry">
        Fout {{ error.statusCode }}
      </p>
      <h1 class="mt-3 text-4xl font-bold sm:text-5xl">
        {{ notFound ? 'Deze fles is leeg.' : 'Dit was geen goede beslissing.' }}
      </h1>
      <p class="mx-auto mt-4 max-w-prose text-smoke">
        {{ notFound ? 'De pagina die je zoekt bestaat niet (meer). Misschien is hij verplaatst, of heeft iemand hem opgedronken.' : 'Er ging iets mis aan onze kant. Probeer het later nog eens.' }}
      </p>
      <div class="mt-8 flex flex-wrap justify-center gap-3">
        <button
          type="button"
          class="btn btn-sherry"
          @click="clearError({ redirect: '/' })"
        >
          Terug naar de startpagina
        </button>
        <NuxtLink
          to="/proeverijen"
          class="btn btn-ghost-light"
          @click="clearError()"
        >
          Bekijk de agenda
        </NuxtLink>
      </div>
    </section>
  </NuxtLayout>
</template>
